function validate(input) {
  const [{ Employee = [] }] = input;
  const ids = new Set();
  for (const [id, team] of Employee) {
    if (id === null) return 'Every employee needs an employee_id.';
    if (ids.has(id)) return `employee_id ${id} appears twice in Employee.`;
    if (team === null) return `Employee ${id} needs a team_id.`;
    ids.add(id);
  }
  return null;
}

reference:
SELECT employee_id,
  COUNT(*) OVER (
    PARTITION BY team_id
  ) AS team_size
FROM Employee;

generator:
function generate(rand, size) {
  const small = size === 'small';
  const count = small ? Math.floor(rand() * 9) : 2000;
  const teams = small ? 1 + Math.floor(rand() * 4) : 150;
  // Shuffle the ids so the table is not ordered by employee_id.
  const ids = Array.from({ length: count }, (_, i) => i + 1);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const Employee = ids.map(id => [id, 1 + Math.floor(rand() * teams)]);
  return [{ Employee }];
}
